package net.zartra.gui;
import org.junit.Test;import static org.junit.Assert.*;
public class Goal2PaginationHistoryTest {@Test public void paginationCalculatesBoundsStaticAndContent(){MenuDefinition m=new MenuDefinition("pages","Pages",3);m.paginationContentSlots.add(0);m.paginationContentSlots.add(1);for(int n=0;n<5;n++){MenuItem i=new MenuItem(new org.bukkit.inventory.ItemStack(org.bukkit.Material.STONE),null);i.priority=n;m.items.put(n,i);}m.items.put(8,new MenuItem(new org.bukkit.inventory.ItemStack(org.bukkit.Material.DIRT),null));assertEquals(3,MenuPagination.pages(m));assertEquals(1,MenuPagination.page(m,0));assertEquals(3,MenuPagination.page(m,99));assertEquals(2,MenuPagination.pageItems(m,2).size());}@Test public void boundedHistoryInvalidatesRedo(){EditorHistory<String> h=new EditorHistory<String>(3);h.push("a");h.push("b");h.push("c");assertEquals("b",h.undo());h.push("x");assertNull(h.redo());h.push("d");assertEquals(3,h.size());}}